    def transaction(
        self, requests: Iterable[TransactionClientMessage]
    ) -> Iterator[TransactionServerMessage]:
        """Transaction stream. The first client message must be
        BeginTransactionRequest. Stream close before commit aborts the transaction.
        """
        return _support.map_recv(
            self._stub.Transaction(
                _support.map_send(requests, _codec.to_wire_transaction_client_message)
            ),
            _codec.from_wire_transaction_server_message,
        )
